import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CSS/Cart.css';

const Cart = () => {
  const [cartItems, setCartItems] = useState([]);

  const loadCart = () => {
    const storedCart = JSON.parse(localStorage.getItem('cartItems')) || [];
    setCartItems(storedCart);
  };

  useEffect(() => {
    loadCart();
    window.addEventListener('cartUpdated', loadCart);
    return () => {
      window.removeEventListener('cartUpdated', loadCart);
    };
  }, []);

  const updateQuantity = (id, delta) => {
    const updatedCart = cartItems.map(item => {
      if (item._id === id || item.id === id) {
        const newQty = item.quantity + delta;
        return newQty > 0 ? { ...item, quantity: newQty } : item;
      }
      return item;
    });

    setCartItems(updatedCart);
    localStorage.setItem('cartItems', JSON.stringify(updatedCart));
    window.dispatchEvent(new Event('cartUpdated'));
  };

  const removeItem = (id) => {
    const updatedCart = cartItems.filter(item => (item._id !== id && item.id !== id));
    setCartItems(updatedCart);
    localStorage.setItem('cartItems', JSON.stringify(updatedCart));
    window.dispatchEvent(new Event('cartUpdated'));
  };

  // Checkout Handler to send order to backend
  const handleCheckout = async () => {
    if (cartItems.length === 0) return;

    try {
      const response = await axios.post('http://localhost:4000/api/seller/orders', {
        items: cartItems,
        customerName: 'Janan' // You can change or make this dynamic later
      });

      if (response.data.success) {
        alert('Order placed successfully!');
        // Clear local storage cart
        localStorage.removeItem('cartItems');
        window.dispatchEvent(new Event('cartUpdated'));
        // Redirect to My Orders page
        window.location.href = '/orders'; // Match your router path for orders
      }
    } catch (err) {
      console.error('Checkout failed:', err);
      alert('Checkout failed. Please check your backend connection.');
    }
  };

  const subtotal = cartItems.reduce((acc, item) => acc + (Number(item.price) || 0) * item.quantity, 0);
  const shipping = subtotal > 0 ? 150 : 0;
  const total = subtotal + shipping;

  return (
    <div className="cart-page">
      <div className="cart-header">
        <span className="cart-tag">SECURE CHECKOUT</span>
        <h1>Shopping Cart</h1>
        <p>You have {cartItems.reduce((acc, item) => acc + item.quantity, 0)} item(s) in your cart.</p>
      </div>

      {cartItems.length === 0 ? (
        <div className="empty-cart-container">
          <div className="empty-cart-icon">🛒</div>
          <h2>Your cart is empty</h2>
          <p>Looks like you haven't added anything to your cart yet.</p>
          <a href="/products" className="cart-btn-primary">Start Shopping</a>
        </div>
      ) : (
        <div className="cart-grid-wrapper">
          {/* Left Side: Cart Items List */}
          <div className="cart-items-list">
            {cartItems.map(item => {
              const itemId = item._id || item.id;
              return (
                <div className="cart-card" key={itemId}>
                  <div className="cart-img-box">
                    <img 
                      src={item.image} 
                      alt={item.title} 
                      onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }}
                    />
                  </div>
                  
                  <div className="cart-details-box">
                    <span className="cart-item-cat">{item.category}</span>
                    <h3>{item.title}</h3>
                    <div className="cart-price-group">
                      <span className="cart-current-price">${Number(item.price).toLocaleString()}</span>
                      {item.originalPrice && (
                        <span className="cart-old-price">${Number(item.originalPrice).toLocaleString()}</span>
                      )}
                    </div>
                  </div>

                  <div className="cart-actions-box">
                    <div className="qty-selector">
                      <button onClick={() => updateQuantity(itemId, -1)}>-</button>
                      <span>{item.quantity}</span>
                      <button onClick={() => updateQuantity(itemId, 1)}>+</button>
                    </div>
                    <button className="item-delete-btn" onClick={() => removeItem(itemId)}>
                      <i className="fa-regular fa-trash-can"></i> Remove
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Right Side: Order Summary Card */}
          <div className="cart-summary-box">
            <h2>Order Summary</h2>
            
            <div className="summary-line">
              <span>Subtotal</span>
              <span>${subtotal.toLocaleString()}</span>
            </div>
            
            <div className="summary-line">
              <span>Estimated Shipping</span>
              <span>{shipping === 0 ? 'Free' : `$${shipping}`}</span>
            </div>

            <div className="summary-line discount">
              <span>Promo Discount</span>
              <span>-$0</span>
            </div>

            <hr className="summary-sep" />

            <div className="summary-line total-line">
              <span>Total Amount</span>
              <span>${total.toLocaleString()}</span>
            </div>

            <button className="checkout-action-btn" onClick={handleCheckout}>
              Proceed to Checkout
            </button>
            
            <div className="secure-badge">
              <i className="fa-solid fa-lock"></i> Safe and Secure Payments
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cart;
